import * as THREE from "three";

/**
 * Realistic avatar engine built on the CC0 MakeHuman (hm08) base mesh.
 * Assets are generated by scripts/avatar/build_assets.py into /public/avatar.
 * Body shape = base mesh + weighted sum of sparse morph targets, evaluated on the CPU,
 * then scaled to the exact height. Hair/brows/lashes/eyes are fitted proxies that follow every morph.
 */

type Buf = { offset: number; count: number; type: "f32" | "u32" | "u16" };
export type Manifest = {
  buffers: Record<string, Buf>; vertexCount: number; targets: Record<string, number>;
  bones: { name: string; parent: string | null; head: string; tail: string }[];
  joints: Record<string, number[]>;
  proxies: Record<string, { scales: Record<string, [number, number, number]>; verts: number }>;
  textures: Record<string, string>;
};
export type HumanData = { m: Manifest; buf: ArrayBuffer; f32: (n: string) => Float32Array; u32: (n: string) => Uint32Array; u16: (n: string) => Uint16Array };

let loading: Promise<HumanData> | null = null;
export function loadHuman(): Promise<HumanData> {
  if (!loading) {
    loading = Promise.all([fetch("/avatar/avatar.json").then((r) => r.json()), fetch("/avatar/avatar.bin").then((r) => r.arrayBuffer())]).then(([m, buf]: [Manifest, ArrayBuffer]) => {
      const view = <T,>(n: string, C: new (b: ArrayBuffer, o: number, c: number) => T) => { const b = m.buffers[n]; if (!b) throw new Error("missing " + n); return new C(buf, b.offset, b.count); };
      return { m, buf, f32: (n) => view(n, Float32Array), u32: (n) => view(n, Uint32Array), u16: (n) => view(n, Uint16Array) };
    });
    loading.catch(() => { loading = null; });
  }
  return loading;
}

// ── shape parameters ─────────────────────────────────────────────
export type HumanShape = {
  heightCm: number;
  weight: number; muscle: number; // 0..1, 0.5 = average
  bust: number; cup: number; firmness: number; underbust: number; waist: number; hips: number; // -1..1
  belly: number; glutes: number; shoulders: number; arms: number; thighs: number; calves: number; neck: number; legLength: number; // -1..1 (belly 0..1)
  african: number; asian: number; european: number; // face/body heritage mix
  headShape: "oval" | "round" | "heart" | "square"; headShapeAmount: number; faceFullness: number;
  noseWidth: number; noseLength: number; lipsWidth: number; lipsFullness: number; eyeSize: number;
};

const pos = (v: number) => Math.max(0, v), neg = (v: number) => Math.max(0, -v);

/** Conservative limits so body-part morphs stay natural and modest. */
const LIMITS: Partial<Record<keyof HumanShape, [number, number]>> = {
  bust: [-0.3, 0.3], cup: [-0.3, 0.15], firmness: [0, 0.3], underbust: [-0.3, 0.3], glutes: [-0.25, 0.25], belly: [-0.25, 0.2],
  hips: [-0.45, 0.45], waist: [-0.45, 0.45], thighs: [-0.35, 0.35], arms: [-0.35, 0.35], calves: [-0.3, 0.3], shoulders: [-0.3, 0.3],
  legLength: [-0.3, 0.3], neck: [-0.2, 0.2],
};
export function clampShape<T extends HumanShape>(s: T): T {
  const o = { ...s };
  for (const [k, [lo, hi]] of Object.entries(LIMITS) as [keyof HumanShape, [number, number]][]) (o as Record<string, unknown>)[k] = Math.max(lo, Math.min(hi, (s[k] as number) ?? 0));
  return o;
}

export function targetWeights(input: HumanShape): Record<string, number> {
  const s = clampShape(input);
  const w: Record<string, number> = {};
  const add = (n: string, v: number) => { if (Math.abs(v) > 1e-4) w[n] = (w[n] ?? 0) + v; };
  const tot = s.african + s.asian + s.european || 1;
  add("macrodetails/african-female-young", s.african / tot);
  add("macrodetails/asian-female-young", s.asian / tot);
  add("macrodetails/caucasian-female-young", s.european / tot);
  const lvl = (x: number) => ({ min: pos(0.5 - x) * 2, average: 1 - Math.abs(x - 0.5) * 2, max: pos(x - 0.5) * 2 });
  const cm = lvl(s.muscle), cw = lvl(s.weight);
  for (const m of ["min", "average", "max"] as const)
    for (const wt of ["min", "average", "max"] as const)
      if (!(m === "average" && wt === "average")) add(`macrodetails/universal-female-young-${m}muscle-${wt}weight`, cm[m] * cw[wt]);
  const hN = Math.max(-1, Math.min(1, (s.heightCm - 165) / 20));
  add("macrodetails/height/female-young-averagemuscle-averageweight-maxheight", pos(hN) * 0.8);
  add("macrodetails/height/female-young-averagemuscle-averageweight-minheight", neg(hN) * 0.8);
  add("breast/female-young-averagemuscle-averageweight-maxcup-averagefirmness", pos(s.cup));
  add("breast/female-young-averagemuscle-averageweight-mincup-averagefirmness", neg(s.cup));
  add("breast/female-young-averagemuscle-averageweight-averagecup-maxfirmness", pos(s.firmness));
  add("breast/female-young-averagemuscle-averageweight-averagecup-minfirmness", neg(s.firmness));
  const meas: [keyof HumanShape, string][] = [["bust", "bust-circ"], ["underbust", "underbust-circ"], ["waist", "waist-circ"], ["hips", "hips-circ"], ["shoulders", "shoulder-dist"], ["arms", "upperarm-circ"], ["thighs", "thigh-circ"], ["calves", "calf-circ"], ["neck", "neck-circ"]];
  for (const [k, n] of meas) { const v = s[k] as number; add(`measure/measure-${n}-incr`, pos(v)); add(`measure/measure-${n}-decr`, neg(v)); }
  add("measure/measure-upperleg-height-incr", pos(s.legLength)); add("measure/measure-upperleg-height-decr", neg(s.legLength));
  add("measure/measure-lowerleg-height-incr", pos(s.legLength)); add("measure/measure-lowerleg-height-decr", neg(s.legLength));
  add("stomach/stomach-pregnant-incr", pos(s.belly)); add("stomach/stomach-pregnant-decr", neg(s.belly));
  add("buttocks/buttocks-volume-incr", pos(s.glutes)); add("buttocks/buttocks-volume-decr", neg(s.glutes));
  add({ oval: "head/head-oval", round: "head/head-round", heart: "head/head-invertedtriangular", square: "head/head-square" }[s.headShape], s.headShapeAmount);
  add("head/head-fat-incr", pos(s.faceFullness)); add("head/head-fat-decr", neg(s.faceFullness));
  add("nose/nose-scale-horiz-incr", pos(s.noseWidth)); add("nose/nose-scale-horiz-decr", neg(s.noseWidth));
  add("nose/nose-scale-vert-incr", pos(s.noseLength)); add("nose/nose-scale-vert-decr", neg(s.noseLength));
  add("mouth/mouth-scale-horiz-incr", pos(s.lipsWidth)); add("mouth/mouth-scale-horiz-decr", neg(s.lipsWidth));
  add("mouth/mouth-scale-vert-incr", pos(s.lipsFullness)); add("mouth/mouth-scale-vert-decr", neg(s.lipsFullness));
  for (const side of ["l", "r"]) { add(`eyes/${side}-eye-scale-incr`, pos(s.eyeSize)); add(`eyes/${side}-eye-scale-decr`, neg(s.eyeSize)); }
  return w;
}

// ── morph evaluation ─────────────────────────────────────────────
export type Morphed = { pos: Float32Array; bodyNormals: Float32Array; joints: (name: string) => THREE.Vector3; scale: number };

export function morph(d: HumanData, s: HumanShape): Morphed {
  const base = d.f32("basePos");
  const p = new Float32Array(base);
  for (const [name, wt] of Object.entries(targetWeights(s))) {
    if (!d.m.targets[name]) continue;
    const idx = d.u32(`t:${name}:i`), dl = d.f32(`t:${name}:d`);
    for (let i = 0; i < idx.length; i++) {
      const o = idx[i] * 3;
      p[o] += dl[i * 3] * wt; p[o + 1] += dl[i * 3 + 1] * wt; p[o + 2] += dl[i * 3 + 2] * wt;
    }
  }
  // scale to exact height and stand on the ground (measured on rendered body vertices only)
  const split = d.u32("bodySplit");
  let minY = Infinity, maxY = -Infinity;
  for (let i = 0; i < split.length; i++) { const y = p[split[i] * 3 + 1]; if (y < minY) minY = y; if (y > maxY) maxY = y; }
  const scale = s.heightCm / 100 / (maxY - minY);
  for (let i = 0; i < p.length; i += 3) { p[i] *= scale; p[i + 1] = (p[i + 1] - minY) * scale; p[i + 2] *= scale; }

  bakeStance(d, p);
  modestySmooth(d, p);
  let floor = Infinity;
  for (let i = 0; i < split.length; i++) floor = Math.min(floor, p[split[i] * 3 + 1]);
  for (let i = 1; i < p.length; i += 3) p[i] -= floor;

  // smooth normals on the original (unsplit) topology so UV seams don't show
  const idx = d.u32("bodyIndex");
  const n = new Float32Array(p.length);
  const a = new THREE.Vector3(), b = new THREE.Vector3(), c = new THREE.Vector3(), ab = new THREE.Vector3(), ac = new THREE.Vector3();
  for (let t = 0; t < idx.length; t += 3) {
    const i0 = split[idx[t]], i1 = split[idx[t + 1]], i2 = split[idx[t + 2]];
    a.fromArray(p, i0 * 3); b.fromArray(p, i1 * 3); c.fromArray(p, i2 * 3);
    ab.subVectors(b, a); ac.subVectors(c, a); ab.cross(ac);
    for (const i of [i0, i1, i2]) { n[i * 3] += ab.x; n[i * 3 + 1] += ab.y; n[i * 3 + 2] += ab.z; }
  }
  for (let i = 0; i < n.length; i += 3) { const l = Math.hypot(n[i], n[i + 1], n[i + 2]) || 1; n[i] /= l; n[i + 1] /= l; n[i + 2] /= l; }
  const cache = new Map<string, THREE.Vector3>();
  const joints = (name: string) => {
    let v = cache.get(name);
    if (!v) {
      const ids = d.m.joints[name] ?? [];
      v = new THREE.Vector3();
      for (const i of ids) v.x += p[i * 3], v.y += p[i * 3 + 1], v.z += p[i * 3 + 2];
      v.divideScalar(ids.length || 1);
      cache.set(name, v);
    }
    return v;
  };
  return { pos: p, bodyNormals: n, joints, scale };
}

/**
 * MakeHuman's rest pose stands with the feet wide apart. Dresses hang badly around that, so the legs are
 * rotated inward about the hip joints (blended by each vertex's leg skin weight) into a natural stance.
 */
function bakeStance(d: HumanData, p: Float32Array) {
  const si = d.u16("skinIndex"), sw = d.f32("skinWeight");
  const jointAt = (name: string) => {
    const ids = d.m.joints[name] ?? [];
    const v = new THREE.Vector3();
    for (const i of ids) v.x += p[i * 3], v.y += p[i * 3 + 1], v.z += p[i * 3 + 2];
    return v.divideScalar(ids.length || 1);
  };
  // arms: lower from the A-pose to a relaxed stance (done in the rest mesh so the chest never deforms at render time)
  for (const side of ["L", "R"] as const) {
    const sh = jointAt(`upperarm01.${side}____head`), el = jointAt(`lowerarm01.${side}____head`);
    const a = Math.atan2(Math.abs(el.x - sh.x), sh.y - el.y);
    const ang = (side === "L" ? -1 : 1) * (a - 0.13);
    const cos = Math.cos(ang), sin = Math.sin(ang);
    const armBone = d.m.bones.map((b) => new RegExp(`^(upperarm|lowerarm|wrist|finger|metacarpal|thumb)[^.]*\.${side}$`).test(b.name));
    for (let i = 0; i < d.m.vertexCount; i++) {
      let w = 0;
      for (let k = 0; k < 4; k++) if (armBone[si[i * 4 + k]]) w += sw[i * 4 + k];
      if (w <= 0) continue;
      const x = p[i * 3] - sh.x, y = p[i * 3 + 1] - sh.y;
      const rx = x * cos - y * sin, ry = x * sin + y * cos;
      p[i * 3] += (rx - x) * w; p[i * 3 + 1] += (ry - y) * w;
    }
  }
  for (const side of ["L", "R"] as const) {
    const hip = jointAt(`upperleg01.${side}____head`), ankle = jointAt(`foot.${side}____head`);
    const sign = side === "L" ? 1 : -1;
    const cur = Math.atan2(ankle.x - hip.x, hip.y - ankle.y);
    const want = Math.atan2(sign * 0.055 - hip.x, hip.y - ankle.y);
    const ang = want - cur; // rotation about +z
    const cos = Math.cos(ang), sin = Math.sin(ang);
    const legBone = d.m.bones.map((b) => new RegExp(`^(upperleg|lowerleg|foot|toe)[^.]*\.${side}$`).test(b.name));
    for (let i = 0; i < d.m.vertexCount; i++) {
      let w = 0;
      for (let k = 0; k < 4; k++) if (legBone[si[i * 4 + k]]) w += sw[i * 4 + k];
      if (w <= 0) continue;
      const x = p[i * 3] - hip.x, y = p[i * 3 + 1] - hip.y;
      const rx = x * cos - y * sin, ry = x * sin + y * cos;
      p[i * 3] += (rx - x) * w; p[i * 3 + 1] += (ry - y) * w;
    }
  }
}

// ── modesty ─────────────────────────────────────────────
let modestyCache: { verts: Uint32Array; weight: Float32Array; nb: Uint32Array[] } | null = null;
/** Vertices around the chest (weighted by breast/chest skin weight) with their mesh neighbours. */
function modestyRegion(d: HumanData) {
  if (modestyCache) return modestyCache;
  const si = d.u16("skinIndex"), sw = d.f32("skinWeight");
  const chestBone = d.m.bones.map((b) => /^breast/.test(b.name));
  const w = new Float32Array(d.m.vertexCount);
  for (let i = 0; i < d.m.vertexCount; i++) for (let k = 0; k < 4; k++) if (chestBone[si[i * 4 + k]]) w[i] += sw[i * 4 + k];
  const split = d.u32("bodySplit"), idx = d.u32("bodyIndex");
  const nbSets = new Map<number, Set<number>>();
  for (let t = 0; t < idx.length; t += 3) {
    const v = [split[idx[t]], split[idx[t + 1]], split[idx[t + 2]]];
    for (let e = 0; e < 3; e++) {
      const a = v[e], b = v[(e + 1) % 3];
      if (w[a] <= 0 && w[b] <= 0) continue;
      if (!nbSets.has(a)) nbSets.set(a, new Set()); if (!nbSets.has(b)) nbSets.set(b, new Set());
      nbSets.get(a)!.add(b); nbSets.get(b)!.add(a);
    }
  }
  const verts = new Uint32Array([...nbSets.keys()].filter((v) => w[v] > 0));
  modestyCache = { verts, weight: w, nb: Array.from(verts, (v) => new Uint32Array(nbSets.get(v)!)) };
  return modestyCache;
}

export const MODESTY = { iterations: 30 };
/**
 * Modesty shaping of the chest: the front chest surface is replaced by a 2D Gaussian blend of itself
 * (sigma 3.5 cm), so it becomes a soft rounded form with no anatomical detail and no pointed apex.
 * Blended by breast skin weight so it joins the rest of the body seamlessly.
 */
function modestySmooth(d: HumanData, p: Float32Array) {
  const { verts, weight } = modestyRegion(d);
  const front = Array.from(verts).filter((v) => p[v * 3 + 2] > 0);
  if (!front.length) return;
  const SIG2 = 2 * 0.035 * 0.035;
  const z0 = front.map((v) => p[v * 3 + 2]);
  const blurred = front.map((v) => {
    let s = 0, ws = 0;
    for (let j = 0; j < front.length; j++) {
      const u = front[j], dx = p[u * 3] - p[v * 3], dy = p[u * 3 + 1] - p[v * 3 + 1];
      const w = Math.exp(-(dx * dx + dy * dy) / SIG2);
      s += z0[j] * w; ws += w;
    }
    return s / ws;
  });
  front.forEach((v, i) => {
    const t = Math.min(1, weight[v] * 2.5);
    p[v * 3 + 2] = z0[i] + (blurred[i] - z0[i]) * t;
  });
  // light relaxation afterwards to remove any blending seams
  const { nb } = modestyRegion(d);
  const vs = modestyRegion(d).verts;
  for (let it = 0; it < MODESTY.iterations; it++) {
    const nx = new Float32Array(vs.length * 3);
    for (let k = 0; k < vs.length; k++) {
      const v = vs[k], n = nb[k];
      let x = 0, y = 0, z = 0;
      for (const j of n) { x += p[j * 3]; y += p[j * 3 + 1]; z += p[j * 3 + 2]; }
      const s = Math.min(1, weight[v] * 3) * 0.5;
      nx[k * 3] = p[v * 3] + s * (x / n.length - p[v * 3]); nx[k * 3 + 1] = p[v * 3 + 1] + s * (y / n.length - p[v * 3 + 1]); nx[k * 3 + 2] = p[v * 3 + 2] + s * (z / n.length - p[v * 3 + 2]);
    }
    for (let k = 0; k < vs.length; k++) { const v = vs[k]; p[v * 3] = nx[k * 3]; p[v * 3 + 1] = nx[k * 3 + 1]; p[v * 3 + 2] = nx[k * 3 + 2]; }
  }
}

/** UV areas of the areolae on the skin texture (front-most chest vertex on each side), used to paint them out. */
export function modestyUVs(d: HumanData): { u: number; v: number; r: number }[] {
  const base = d.f32("basePos"), split = d.u32("bodySplit"), uv = d.f32("bodyUv");
  const { verts } = modestyRegion(d);
  const out: { u: number; v: number; r: number }[] = [];
  for (const side of [1, -1]) {
    let best = -1, bz = -Infinity;
    for (const v of verts) if (Math.sign(base[v * 3]) === side && base[v * 3 + 2] > bz) { bz = base[v * 3 + 2]; best = v; }
    if (best < 0) continue;
    const near: number[] = [];
    for (const v of verts) {
      const dd = Math.hypot(base[v * 3] - base[best * 3], base[v * 3 + 1] - base[best * 3 + 1], base[v * 3 + 2] - base[best * 3 + 2]);
      if (dd < 0.035) near.push(v);
    }
    const uvs: [number, number][] = [];
    for (let i = 0; i < split.length; i++) if (near.includes(split[i])) uvs.push([uv[i * 2], uv[i * 2 + 1]]);
    const cu = uvs.reduce((s, q) => s + q[0], 0) / uvs.length, cv = uvs.reduce((s, q) => s + q[1], 0) / uvs.length;
    const r = Math.max(0.012, ...uvs.map((q) => Math.hypot(q[0] - cu, q[1] - cv)));
    out.push({ u: cu, v: cv, r });
  }
  return out;
}

/** Fills a render-vertex (split) position/normal attribute from per-vertex arrays. */
export function writeSplit(split: Uint32Array, src: Float32Array, dst: Float32Array) {
  for (let i = 0; i < split.length; i++) { const o = split[i] * 3; dst[i * 3] = src[o]; dst[i * 3 + 1] = src[o + 1]; dst[i * 3 + 2] = src[o + 2]; }
}

/** MakeHuman proxy fitting: each proxy vertex = barycentric blend of 3 body vertices + scaled offset. */
export function fitProxy(d: HumanData, key: string, P: Float32Array): Float32Array {
  const refs = d.u32(`p:${key}:refs`), w = d.f32(`p:${key}:w`), off = d.f32(`p:${key}:off`);
  const sc = d.m.proxies[key].scales;
  const axisScale = (k: "x" | "y" | "z", axis: number) => {
    const s = sc[k]; if (!s) return 1;
    return Math.abs(P[s[0] * 3 + axis] - P[s[1] * 3 + axis]) / s[2];
  };
  // MakeHuman scale refs measure in the base frame; our positions are already scaled to height, which the ratio absorbs
  const sx = axisScale("x", 0), sy = axisScale("y", 1), sz = axisScale("z", 2);
  const nv = refs.length / 3, out = new Float32Array(nv * 3);
  for (let i = 0; i < nv; i++) {
    for (let k = 0; k < 3; k++) {
      const r = refs[i * 3 + k] * 3, wk = w[i * 3 + k];
      out[i * 3] += P[r] * wk; out[i * 3 + 1] += P[r + 1] * wk; out[i * 3 + 2] += P[r + 2] * wk;
    }
    out[i * 3] += off[i * 3] * sx; out[i * 3 + 1] += off[i * 3 + 1] * sy; out[i * 3 + 2] += off[i * 3 + 2] * sz;
  }
  return out;
}

// ── body regions (from skin weights) ─────────────────────────────────────────────
export type Region = "head" | "neck" | "torso" | "breast" | "arm" | "forearm" | "hand" | "pelvis" | "thigh" | "shin" | "foot";
export function regionOfBone(name: string): Region {
  if (/^(head|jaw|eye|oculi|tongue|levator|oris|special|risorius|temporalis|orbicularis|platysma|mastoid|ear)/.test(name)) return "head";
  if (/^neck/.test(name)) return "neck";
  if (/^breast/.test(name)) return "breast";
  if (/^(upperarm|shoulder|clavicle)/.test(name)) return name.startsWith("upperarm02") || name.startsWith("upperarm01") ? "arm" : "torso";
  if (/^lowerarm/.test(name)) return "forearm";
  if (/^(wrist|finger|metacarpal|thumb)/.test(name)) return "hand";
  if (/^(pelvis|root)/.test(name)) return "pelvis";
  if (/^upperleg/.test(name)) return "thigh";
  if (/^lowerleg/.test(name)) return "shin";
  if (/^(foot|toe)/.test(name)) return "foot";
  return "torso";
}
let regionCache: { regions: Region[]; boneOf: Uint16Array } | null = null;
export function vertexRegions(d: HumanData) {
  if (regionCache) return regionCache;
  const si = d.u16("skinIndex"), sw = d.f32("skinWeight");
  const n = d.m.vertexCount, regions: Region[] = new Array(n), boneOf = new Uint16Array(n);
  const boneRegion = d.m.bones.map((b) => regionOfBone(b.name));
  for (let i = 0; i < n; i++) {
    // dominant region by summed weight
    const acc = new Map<Region, number>();
    for (let k = 0; k < 4; k++) { const wgt = sw[i * 4 + k]; if (wgt > 0) acc.set(boneRegion[si[i * 4 + k]], (acc.get(boneRegion[si[i * 4 + k]]) ?? 0) + wgt); }
    let best: Region = "torso", bw = -1;
    for (const [r, v] of acc) if (v > bw) { bw = v; best = r; }
    regions[i] = best; boneOf[i] = si[i * 4];
  }
  regionCache = { regions, boneOf };
  return regionCache;
}

// ── tape measurements (convex hull perimeter of horizontal slices) ─────────────
function hullPerimeter(pts: [number, number][]) {
  if (pts.length < 3) return 0;
  pts.sort((a, b) => a[0] - b[0] || a[1] - b[1]);
  const cross = (o: number[], a: number[], b: number[]) => (a[0] - o[0]) * (b[1] - o[1]) - (a[1] - o[1]) * (b[0] - o[0]);
  const lo: [number, number][] = [], up: [number, number][] = [];
  for (const p of pts) { while (lo.length >= 2 && cross(lo[lo.length - 2], lo[lo.length - 1], p) <= 0) lo.pop(); lo.push(p); }
  for (let i = pts.length - 1; i >= 0; i--) { const p = pts[i]; while (up.length >= 2 && cross(up[up.length - 2], up[up.length - 1], p) <= 0) up.pop(); up.push(p); }
  const h = lo.slice(0, -1).concat(up.slice(0, -1));
  let per = 0;
  for (let i = 0; i < h.length; i++) { const a = h[i], b = h[(i + 1) % h.length]; per += Math.hypot(a[0] - b[0], a[1] - b[1]); }
  return per;
}

export type Measurements = { heightCm: number; bustCm: number; underbustCm: number; waistCm: number; hipCm: number; shoulderCm: number; levels: { bust: number; waist: number; hip: number; shoulder: number; crotch: number; knee: number; ankle: number } };

export function measure(d: HumanData, M: Morphed, heightCm: number): Measurements {
  const { regions } = vertexRegions(d);
  const split = d.u32("bodySplit"), idx = d.u32("bodyIndex"), P = M.pos;
  const slice = (y: number, allow: (r: Region) => boolean) => {
    const pts: [number, number][] = [];
    for (let t = 0; t < idx.length; t += 3) {
      const v = [split[idx[t]], split[idx[t + 1]], split[idx[t + 2]]];
      if (!v.every((i) => allow(regions[i]))) continue;
      for (let e = 0; e < 3; e++) {
        const i0 = v[e], i1 = v[(e + 1) % 3];
        const y0 = P[i0 * 3 + 1], y1 = P[i1 * 3 + 1];
        if ((y0 - y) * (y1 - y) < 0) {
          const f = (y - y0) / (y1 - y0);
          pts.push([P[i0 * 3] + (P[i1 * 3] - P[i0 * 3]) * f, P[i0 * 3 + 2] + (P[i1 * 3 + 2] - P[i0 * 3 + 2]) * f]);
        }
      }
    }
    return hullPerimeter(pts) * 100;
  };
  const sh = M.joints("upperarm01.L____head").y, hipJ = M.joints("upperleg01.L____head").y;
  const span = sh - hipJ;
  const scan = (from: number, to: number, allow: (r: Region) => boolean, pick: "max" | "min") => {
    let best = pick === "max" ? -Infinity : Infinity, at = from;
    for (let k = 0; k <= 10; k++) {
      const y = hipJ + span * (from + ((to - from) * k) / 10);
      const c = slice(y, allow);
      if (c > 0 && (pick === "max" ? c > best : c < best)) { best = c; at = y; }
    }
    return { c: best, y: at };
  };
  const torso = (r: Region) => r === "torso" || r === "breast" || r === "pelvis";
  const lower = (r: Region) => r === "torso" || r === "pelvis" || r === "thigh";
  const bust = scan(0.62, 0.86, torso, "max");
  const waist = scan(0.3, 0.6, torso, "min");
  const hip = scan(-0.12, 0.22, lower, "max");
  const under = slice(bust.y - 0.06 * M.scale * 10, torso);
  const L = M.joints("upperarm01.L____head"), R = M.joints("upperarm01.R____head");
  return {
    heightCm, bustCm: round(bust.c), underbustCm: round(under), waistCm: round(waist.c), hipCm: round(hip.c), shoulderCm: round(L.distanceTo(R) * 100 * 1.08),
    levels: { bust: bust.y, waist: waist.y, hip: hip.y, shoulder: sh, crotch: M.joints("upperleg02.L____head").y, knee: M.joints("lowerleg01.L____head").y, ankle: M.joints("foot.L____head").y },
  };
}
const round = (v: number) => Math.round(v * 2) / 2;

// ── skeleton ─────────────────────────────────────────────
export function createSkeleton(d: HumanData) {
  const bones = d.m.bones.map((b) => { const bone = new THREE.Bone(); bone.name = b.name; return bone; });
  const byName = new Map(bones.map((b) => [b.name, b]));
  d.m.bones.forEach((b, i) => { if (b.parent) byName.get(b.parent)!.add(bones[i]); });
  const roots = bones.filter((_, i) => !d.m.bones[i].parent);
  return { bones, byName, roots, skeleton: new THREE.Skeleton(bones) };
}

/** Moves bones to the morphed joint positions (rest pose, no rotation) and rebinds. */
export function rebindSkeleton(d: HumanData, M: Morphed, sk: ReturnType<typeof createSkeleton>, holder: THREE.Object3D) {
  d.m.bones.forEach((b, i) => {
    const head = M.joints(b.head);
    const parentHead = b.parent ? M.joints(d.m.bones.find((x) => x.name === b.parent)!.head) : new THREE.Vector3();
    sk.bones[i].position.copy(head).sub(parentHead);
    sk.bones[i].quaternion.identity();
  });
  holder.updateMatrixWorld(true);
  sk.skeleton.calculateInverses();
}

// ── skin colour ─────────────────────────────────────────────
export const SKIN_BASES = [
  { key: "skin:young_caucasian_female", avg: "#ce9e83" },
  { key: "skin:young_asian_female", avg: "#ce9d7e" },
  { key: "skin:young_african_female", avg: "#663b2b" },
] as const;

/** Picks the closest real skin texture to a requested tone and returns the tint that shifts it exactly there. */
export function skinFor(hex: string) {
  const target = new THREE.Color(hex);
  const lum = (c: THREE.Color) => 0.2126 * c.r + 0.7152 * c.g + 0.0722 * c.b;
  let best: (typeof SKIN_BASES)[number] = SKIN_BASES[0], bd = Infinity;
  for (const s of SKIN_BASES) {
    const a = new THREE.Color(s.avg);
    const dd = Math.abs(lum(a) - lum(target)) * 4 + Math.abs(a.r / (a.g || 1) - target.r / (target.g || 1)) * 0.2;
    if (dd < bd) { bd = dd; best = s; }
  }
  const avg = new THREE.Color(best.avg);
  const tint = new THREE.Color(Math.min(2, target.r / avg.r), Math.min(2, target.g / avg.g), Math.min(2, target.b / avg.b));
  return { texture: best.key, tint };
}

// ── match measurements ─────────────────────────────────────────────
/**
 * Adjusts shape sliders so the avatar's tape measurements match the customer's (cm).
 * Uses a few damped secant steps per dimension (bust→bust, waist→waist, hip→hips). Returns the new shape.
 */
export function fitToMeasurements<T extends HumanShape>(d: HumanData, shape: T, target: { bustCm: number; waistCm: number; hipCm: number }): T {
  let s = { ...shape };
  const pairs: [keyof HumanShape, "bustCm" | "waistCm" | "hipCm"][] = [["bust", "bustCm"], ["waist", "waistCm"], ["hips", "hipCm"]];
  const read = (x: HumanShape) => measure(d, morph(d, x), x.heightCm);
  for (let pass = 0; pass < 3; pass++) {
    for (const [k, m] of pairs) {
      const cur = read(s)[m];
      const step = 0.25;
      const probe = { ...s, [k]: Math.max(-1, Math.min(1, (s[k] as number) + step)) };
      const slope = (read(probe)[m] - cur) / step || 10;
      const next = Math.max(-1, Math.min(1, (s[k] as number) + ((target[m] - cur) / slope) * 0.9));
      s = clampShape({ ...s, [k]: next });
    }
  }
  return s;
}
